-- URL-only page snapshots stay in the existing atomically committed 4000-byte
-- cursor. No title/body copies, new queue, table, public grant or source reset.
create function private.collector_cloud_frozen_cursor_valid(c jsonb,slug text)
returns boolean language plpgsql immutable set search_path=pg_catalog as $$
declare u jsonb; path_pattern text; listing_pattern text; count_urls integer;
begin
 if not (c ? 'frozen_urls') then return not (c ? 'frozen_next'); end if;
 if slug not in ('ec','eu-parliament') or jsonb_typeof(c->'frozen_urls') is distinct from 'array' then return false; end if;
 count_urls=jsonb_array_length(c->'frozen_urls');
 if count_urls not between 1 and 100 or octet_length(c::text)>4000 or not (c ? 'frozen_next') then return false; end if;
 if jsonb_typeof(c->'offset') is distinct from 'number' or (c->>'offset') !~ '^[0-9]{1,6}$' or (c->>'offset')::integer>count_urls then return false; end if;
 if slug='ec' then
  path_pattern='^https://ec[.]europa[.]eu/commission/presscorner/detail/en/(ip|qanda|statement|speech|memo|mex)_[0-9]{2}_[0-9]+$';
  listing_pattern='^https://ec[.]europa[.]eu/commission/presscorner/api/search[?][^#]+$';
 else
  path_pattern='^https://www[.]europarl[.]europa[.]eu/news/en/press-room/[0-9]{8}IPR[0-9]+/[^?#]*$';
  listing_pattern='^https://www[.]europarl[.]europa[.]eu/rss/doc/press-releases/en[.]xml$';
 end if;
 if c->>'page' !~ listing_pattern then return false; end if;
 if jsonb_typeof(c->'frozen_next') not in ('null','string') then return false; end if;
 if c->'frozen_next'<>'null'::jsonb and (slug='eu-parliament' or c->>'frozen_next' !~ listing_pattern) then return false; end if;
 for u in select value from jsonb_array_elements(c->'frozen_urls') loop
  if jsonb_typeof(u) is distinct from 'string' or u#>>'{}' !~ path_pattern or octet_length(u#>>'{}')>2048 then return false; end if;
 end loop;
 if (select count(distinct value) from jsonb_array_elements(c->'frozen_urls'))<>count_urls then return false; end if;
 return true;
end; $$;
revoke all on function private.collector_cloud_frozen_cursor_valid(jsonb,text) from public,anon,authenticated,service_role;

-- Preserve the existing FTC durable snapshot and lease/retry implementation.
-- Only extend the exact source assignment and host clauses; fail on drift.
do $routing$
declare definition text; expected text;
begin
 definition=pg_get_functiondef('public.collector_cloud_take(text,text)'::regprocedure);
 expected=$guard$slug in ('oecd','ftc')$guard$;
 if position(expected in definition)=0 then raise exception 'cloud source assignment contract drift'; end if;
 execute replace(definition,expected,$guard$slug in ('oecd','ftc','ec','eu-parliament')$guard$);
 definition=pg_get_functiondef('private.collector_cloud_cursor_valid(jsonb,text)'::regprocedure);
 expected=$guard$case when slug='ftc' then '^https://www[.]ftc[.]gov/' else '^https://www[.]oecd[.]org/' end$guard$;
 if position(expected in definition)=0 then raise exception 'cloud cursor validation contract drift'; end if;
 execute replace(definition,expected,$guard$case when slug='ftc' then '^https://www[.]ftc[.]gov/' when slug='oecd' then '^https://www[.]oecd[.]org/' when slug='ec' then '^https://ec[.]europa[.]eu/commission/presscorner/' when slug='eu-parliament' then '^https://www[.]europarl[.]europa[.]eu/' else '^$' end$guard$);
 expected=' foreach field in array';
 if position(expected in definition)=0 then raise exception 'cloud cursor fields contract drift'; end if;
 -- The host replacement above and frozen-field validation must both apply.
 definition=replace(definition,$guard$case when slug='ftc' then '^https://www[.]ftc[.]gov/' else '^https://www[.]oecd[.]org/' end$guard$,$guard$case when slug='ftc' then '^https://www[.]ftc[.]gov/' when slug='oecd' then '^https://www[.]oecd[.]org/' when slug='ec' then '^https://ec[.]europa[.]eu/commission/presscorner/' when slug='eu-parliament' then '^https://www[.]europarl[.]europa[.]eu/' else '^$' end$guard$);
 execute replace(definition,expected,$guard$ if not private.collector_cloud_frozen_cursor_valid(c,slug) then return false; end if;
 foreach field in array$guard$);
end; $routing$;
revoke all on function public.collector_cloud_take(text,text),private.collector_cloud_cursor_valid(jsonb,text) from public,anon,authenticated;
grant execute on function public.collector_cloud_take(text,text) to service_role;
